}

// forcedChange overlays one interval row's post-event state onto an as-of
// evaluation.
type forcedChange struct {
	kind string // "binding", "rolePerm", "scope"
	seq  int64
	on   bool
}

// grantedAt reports the post-event decision for the triple as of atText.
func grantedAt(snap *snapshot, resource, operation, atText string, forced *forcedChange) bool {
	bindingEntries := map[string]bool{}
	for _, row := range snap.bindings {
		active := rowActive(row.effectiveFrom, row.effectiveTo, atText)
		if forced != nil && forced.kind == "binding" && row.seq == forced.seq {
			active = forced.on
		}
		if active {
			bindingEntries[row.roleID] = true
		}
	}
	roles := reachableRoles(bindingEntries, snap.roleParents)

	rolePerms := map[[2]string]bool{}
	for _, row := range snap.rolePerm {
		active := rowActive(row.effectiveFrom, row.effectiveTo, atText)
		if forced != nil && forced.kind == "rolePerm" && row.seq == forced.seq {
			active = forced.on
		}
		if active {
			rolePerms[[2]string{row.roleID, row.permissionID}] = true
		}
	}

	for _, row := range snap.scopes {
		active := rowActive(row.effectiveFrom, row.effectiveTo, atText)
		if forced != nil && forced.kind == "scope" && row.seq == forced.seq {
			active = forced.on
		}
		if !active || !row.scope.matches(resource) {
			continue
		}
		if row.permissionID != "" {
			if permissionCovers(snap, row.permissionID, operation) {
				return true
			}
			continue
		}
		if !roles[row.roleID] {
			continue
		}
		for pair := range rolePerms {
			if pair[0] == row.roleID && permissionCovers(snap, pair[1], operation) {
				return true
			}
		}
	}
	return false
}

// postEventOn reports whether the event row is present after its own event:
// GRANT and UPDATE rows are on; a REVOKE row represents removal, so the
// identity is off.
func postEventOn(event string) bool { return event != "REVOKE" }

// bindingRelevant keeps a binding change when, in the post-event world, the
// bound (or released) role reaches a permission covering the operation through
// a scope pattern matching the resource.
func bindingRelevant(snap *snapshot, row bindingRow, resource, operation string) bool {
	rolePerms := map[[2]string]bool{}
	for _, pair := range snap.rolePerm {
		rolePerms[[2]string{pair.roleID, pair.permissionID}] = true
	}
	reachable := reachableRoles(map[string]bool{row.roleID: true}, snap.roleParents)
	for role := range reachable {
		for pair := range rolePerms {
			if pair[0] != role || !permissionCovers(snap, pair[1], operation) {
				continue
			}
			for _, scope := range snap.scopes {
				if scope.roleID == role && scope.scope.matches(resource) {
					return true
				}
			}
		}
	}
	return false
}

// rolePermRelevant keeps a role/permission change when a scope on that role
// matches the resource and the permission covers the operation, provided the
// role is reachable through some binding interval in the post-event world.
func rolePermRelevant(snap *snapshot, row rolePermRow, resource, operation string) bool {
	if !permissionCovers(snap, row.permissionID, operation) {
		return false
	}
	hasScope := false
	for _, scope := range snap.scopes {
		if scope.roleID == row.roleID && scope.scope.matches(resource) {
			hasScope = true
			break
		}
	}
	if !hasScope {
		return false
	}
	for _, binding := range snap.bindings {
		reachable := reachableRoles(map[string]bool{binding.roleID: true}, snap.roleParents)
		if reachable[row.roleID] {
			return true
		}
	}
	return false
}

// scopeRelevant keeps a scope change whose pattern matches the resource and
// whose (role, permission) or direct permission covers the operation, with
// role reachability through some binding interval.
func scopeRelevant(snap *snapshot, row scopeRow, resource, operation string) bool {
	if !row.scope.matches(resource) {
		return false
	}
	if row.permissionID != "" {
		return permissionCovers(snap, row.permissionID, operation)
	}
	covers := false
	for _, pair := range snap.rolePerm {
		if pair.roleID == row.roleID && permissionCovers(snap, pair.permissionID, operation) {
			covers = true
			break
		}
	}
	if !covers {
		return false
	}
	for _, binding := range snap.bindings {
		reachable := reachableRoles(map[string]bool{binding.roleID: true}, snap.roleParents)
		if reachable[row.roleID] {
			return true
		}
	}
	return false
}

func nullable(value string) *string {
	if value == "" {
		return nil
	}
	result := value
	return &result
}

func effectiveToPointer(value string) *string {
	if value == "" {
		return nil
	}
	result := value
	return &result
}

func eventFromBinding(snap *snapshot, row bindingRow, resource, operation string) HistoryEvent {
	granted := grantedAt(snap, resource, operation, row.effectiveFrom,
		&forcedChange{kind: "binding", seq: row.seq, on: postEventOn(row.event)})
	return HistoryEvent{
		Event:         row.event,
		OccurredAt:    row.occurredAt,
		EffectiveFrom: row.effectiveFrom,
		EffectiveTo:   effectiveToPointer(row.effectiveTo),
		Role:          nullable(row.roleID),
		Granted:       granted,
		seq:           row.seq,
	}
}

func eventFromRolePerm(snap *snapshot, row rolePermRow, resource, operation string) HistoryEvent {
	granted := grantedAt(snap, resource, operation, row.effectiveFrom,
		&forcedChange{kind: "rolePerm", seq: row.seq, on: postEventOn(row.event)})
	return HistoryEvent{
		Event:         row.event,
		OccurredAt:    row.occurredAt,
		EffectiveFrom: row.effectiveFrom,
		EffectiveTo:   effectiveToPointer(row.effectiveTo),
		Role:          nullable(row.roleID),
		Permission:    nullable(row.permissionID),
		Granted:       granted,
		seq:           row.seq,
	}
}

func eventFromScope(snap *snapshot, row scopeRow, resource, operation string) HistoryEvent {
	granted := grantedAt(snap, resource, operation, row.effectiveFrom,
		&forcedChange{kind: "scope", seq: row.seq, on: postEventOn(row.event)})
	role := nullable(row.roleID)
	permission := nullable(row.permissionID)
	return HistoryEvent{
		Event:         row.event,
		OccurredAt:    row.occurredAt,
		EffectiveFrom: row.effectiveFrom,
		EffectiveTo:   effectiveToPointer(row.effectiveTo),
		Role:          role,
		Permission:    permission,
		Scope:         nullable(row.scope.text),
		Granted:       granted,
		seq:           row.seq,
	}
}
package authz

import (
	"time"

	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// Service runs the time-aware authorization model over one store.
type Service struct {
	store *store.Store
}

// NewService wraps a store.
func NewService(st *store.Store) *Service { return &Service{store: st} }

// timings carries the canonical UTC texts of one write event.
type timings struct {
	occurredAt    string
	effectiveFrom string
}

// bindingRow is a flattened subject/role interval version.
type bindingRow struct {
	seq           int64
	roleID        string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// rolePermRow is a flattened role/permission interval version.
type rolePermRow struct {
	seq           int64
	roleID        string
	permissionID  string
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// scopeRow is a flattened scoped authorization interval version. Exactly one
// of roleID and permissionID is set.
type scopeRow struct {
	seq           int64
	roleID        string
	permissionID  string
	scope         scopeRef
	event         string
	occurredAt    string
	effectiveFrom string
	effectiveTo   string
	id            int64
}

// snapshot is the complete read model needed for one decision or history
// query. Interval semantics are evaluated in Go in one place.
type snapshot struct {
	bindings []bindingRow
	rolePerm []rolePermRow
	scopes   []scopeRow

	// roleModel holds the current inheritance graph and the static operation
	// coverage of permissions; neither carries history intervals.
	roleModel
}

// roleModel is the history-free read model shared by every query: the
// current role inheritance graph in stored order and the operations
// statically covered by each permission.
type roleModel struct {
	roleParents    map[string][]string
	permOperations map[string]map[string]bool
}

func (s *Service) loadSnapshot(subject string) (*snapshot, error) {
	snap := &snapshot{roleModel: roleModel{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}}

	bindings, scopes, err := s.loadSubjectRows(subject)
	if err != nil {
		return nil, err
	}
	snap.bindings = bindings
	snap.scopes = scopes

	rolePermRows, err := s.loadRolePermissionRows()
	if err != nil {
		return nil, err
	}
	snap.rolePerm = rolePermRows

	model, err := s.loadRoleModel()
	if err != nil {
		return nil, err
	}
	snap.roleModel = model
	return snap, nil
}

// loadSubjectRows reads one subject's binding and scoped authorization
// interval versions. Scope rows that no longer parse are dropped, matching
// the read model everywhere else.
func (s *Service) loadSubjectRows(subject string) ([]bindingRow, []scopeRow, error) {
	bindingVersions, err := s.store.ListBindingVersions(subject)
	if err != nil {
		return nil, nil, err
	}
	bindings := make([]bindingRow, 0, len(bindingVersions))
	for _, version := range bindingVersions {
		bindings = append(bindings, bindingRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}

	scopeVersions, err := s.store.ListScopeVersions(subject)
	if err != nil {
		return nil, nil, err
	}
	scopes := []scopeRow{}
	for _, version := range scopeVersions {
		parsedScope, ok := parseScope(version.ScopeText)
		if !ok {
			continue
		}
		scopes = append(scopes, scopeRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			scope:         parsedScope,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}
	return bindings, scopes, nil
}

// loadRoleModel reads the current inheritance graph and static permission
// operation coverage. Both are present-time definitions without intervals.
func (s *Service) loadRoleModel() (roleModel, error) {
	model := roleModel{
		roleParents:    map[string][]string{},
		permOperations: map[string]map[string]bool{},
	}
	roleIDs, err := s.store.ListCatalog(store.CatalogRole)
	if err != nil {
		return roleModel{}, err
	}
	for _, roleID := range roleIDs {
		parents, err := s.store.RoleParents(roleID)
		if err != nil {
			return roleModel{}, err
		}
		model.roleParents[roleID] = parents
	}

	permissionIDs, err := s.store.ListCatalog(store.CatalogPermission)
	if err != nil {
		return roleModel{}, err
	}
	for _, permissionID := range permissionIDs {
		operations, err := s.store.PermissionOperations(permissionID)
		if err != nil {
			return roleModel{}, err
		}
		set := map[string]bool{}
		for _, operation := range operations {
			set[operation] = true
		}
		model.permOperations[permissionID] = set
	}
	return model, nil
}

// loadRolePermissionRows reads every role/permission grant interval version.
func (s *Service) loadRolePermissionRows() ([]rolePermRow, error) {
	rolePermVersions, err := s.store.ListRolePermissionVersions()
	if err != nil {
		return nil, err
	}
	rows := make([]rolePermRow, 0, len(rolePermVersions))
	for _, version := range rolePermVersions {
		rows = append(rows, rolePermRow{
			seq:           version.Seq,
			roleID:        version.RoleID,
			permissionID:  version.PermissionID,
			event:         version.Event,
			occurredAt:    version.OccurredAt,
			effectiveFrom: version.EffectiveFrom,
			effectiveTo:   version.EffectiveTo,
			id:            version.ID,
		})
	}
	return rows, nil
}

// resolveTimings resolves event and effective times. Both default to now;
// either may be supplied and effectiveFrom need not follow occurredAt.
func (s *Service) resolveTimings(occurredAtText, effectiveFromText string, effectiveField string) (timings, *Failure) {
	now := time.Now().UTC()
	result := timings{occurredAt: FormatTime(now), effectiveFrom: FormatTime(now)}
	if occurredAtText != "" {
		occurred, fail := ParseTime(occurredAtText)
		if fail != nil {
			fail.Field = "occurredAt"
			return timings{}, fail
		}
		result.occurredAt = FormatTime(occurred)
	}
	if effectiveFromText != "" {
		effective, fail := ParseTime(effectiveFromText)
		if fail != nil {
			fail.Field = effectiveField
			return timings{}, fail
		}
		result.effectiveFrom = FormatTime(effective)
	}
	return result, nil
}

// rowActive reports whether the half-open interval [from,to) contains t; an
// empty to marks an open interval.
func rowActive(from, to, at string) bool {
	if from > at {
		return false
	}
	return to == "" || to > at
}

